import json
from docx import Document

TEMPLATE = '/root/offer_letter_template.docx'
DATA = '/root/employee_data.json'
OUT = '/root/offer_letter_filled.docx'

with open(DATA, 'r') as f:
    data = json.load(f)

# Build mapping for placeholders
mapping = {f'{{{{{k}}}}}': str(v) for k, v in data.items()}

relocation_yes = str(data.get('RELOCATION_PACKAGE', '')).strip().lower() == 'yes'

# Helper to replace in a paragraph

def replace_in_paragraph(p, mapping):
    text = p.text
    if not text:
        return
    for key, val in mapping.items():
        if key in text:
            text = text.replace(key, val)
    if text != p.text:
        p.text = text

# Helper to remove paragraph

def remove_paragraph(p):
    p._element.getparent().remove(p._element)
    p._p = p._element = None

# Iterate paragraphs in a container

def process_paragraphs(paragraphs):
    for p in list(paragraphs):
        txt = p.text or ''
        if '{{IF_RELOCATION}}' in txt or '{{END_IF_RELOCATION}}' in txt:
            if relocation_yes:
                txt = txt.replace('{{IF_RELOCATION}}', '').replace('{{END_IF_RELOCATION}}', '')
                p.text = txt
                replace_in_paragraph(p, mapping)
            else:
                remove_paragraph(p)
            continue
        replace_in_paragraph(p, mapping)

# Process document

doc = Document(TEMPLATE)

# Body paragraphs
process_paragraphs(doc.paragraphs)

# Tables
for table in doc.tables:
    for row in table.rows:
        for cell in row.cells:
            process_paragraphs(cell.paragraphs)

# Headers and footers
for section in doc.sections:
    process_paragraphs(section.header.paragraphs)
    process_paragraphs(section.footer.paragraphs)

# Save

doc.save(OUT)
print('Saved', OUT)
